// Glue code only: reshapes/validates the OpenAI API response and pairs
// each returned embedding back to the chunk_id it belongs to (by the
// response's own `index` field, which OpenAI guarantees matches the
// input array position). Does NOT build document/chunk text -- that is
// entirely the Python `indexing` package's job (see Sticky Note: Architecture).
const EXPECTED_DIMENSIONS = 1536;
const EXPECTED_MODEL = 'text-embedding-3-small';

const chunkIds = $('Build embeddings request').item.json.chunk_id;
const response = $json;

if (response.model && response.model !== EXPECTED_MODEL) {
  throw new Error(`Unexpected embedding model in response: ${response.model} (expected ${EXPECTED_MODEL})`);
}

const data = response.data;
if (!Array.isArray(data)) {
  throw new Error('OpenAI embeddings response is missing a "data" array');
}

const results = [];
for (const entry of data) {
  const vector = entry.embedding;
  const chunkId = chunkIds[entry.index];
  if (chunkId === undefined) {
    throw new Error(`No chunk_id at response index ${entry.index}`);
  }
  if (!Array.isArray(vector) || vector.length !== EXPECTED_DIMENSIONS) {
    throw new Error(
      `Chunk ${chunkId}: unexpected embedding dimension ` +
      `${vector ? vector.length : 'missing'} (expected ${EXPECTED_DIMENSIONS}) -- refusing to persist`
    );
  }
  results.push({
    json: {
      chunk_id: chunkId,
      embedding_literal: '[' + vector.join(',') + ']',
      embedding_model: EXPECTED_MODEL,
    },
  });
}

if (results.length !== chunkIds.length) {
  throw new Error(`Expected ${chunkIds.length} embeddings back, got ${results.length}`);
}

return results;
